def num_decodings(s):
    n = len(s)
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1 if s[0] != '0' else 0

    for i in range(2, n + 1):
        one_digit = s[i - 1:i]
        two_digit = s[i - 2:i]

        if one_digit != '0':
            dp[i] += dp[i - 1]
        if 10 <= int(two_digit) <= 26:
            dp[i] += dp[i - 2]

    return dp[n]

